"use client"

import { useMemo, useState } from "react"
import { SearchIcon } from "lucide-react"

import { Input } from "@/components/ui/input"
import { PlaybookCard } from "@/components/livepeer-ui/playbook-card"

import type { SourcePlaybook } from "./daydream-source"

export function SourceCatalog({
  hrefBase,
  playbooks,
  searchPlaceholder = "Search playbooks",
  emptyMessage = "No playbooks match your search.",
}: {
  hrefBase?: string
  playbooks: SourcePlaybook[]
  searchPlaceholder?: string
  emptyMessage?: string
}) {
  const [query, setQuery] = useState("")
  const visible = useMemo(() => {
    const normalized = query.trim().toLowerCase()
    if (!normalized) return playbooks
    return playbooks.filter((playbook) =>
      [
        playbook.title,
        playbook.summary,
        playbook.tags.join(" "),
        playbook.deliverables.join(" "),
      ]
        .join(" ")
        .toLowerCase()
        .includes(normalized)
    )
  }, [playbooks, query])

  return (
    <>
      <div className="relative mx-auto w-full sm:max-w-sm">
        <SearchIcon
          className="pointer-events-none absolute top-1/2 left-3 size-4 -translate-y-1/2 text-muted-foreground"
          aria-hidden="true"
        />
        <Input
          value={query}
          onChange={(event) => setQuery(event.target.value)}
          placeholder={searchPlaceholder}
          className="rounded-sm pl-9"
        />
      </div>

      <div className="mt-8 grid gap-x-4 gap-y-12 md:grid-cols-2 lg:grid-cols-3">
        {visible.map((playbook) => (
          <PlaybookCard
            key={playbook.slug}
            hrefBase={hrefBase}
            playbook={playbook}
          />
        ))}
      </div>

      {visible.length === 0 && (
        <p className="py-16 text-center text-sm text-muted-foreground">
          {emptyMessage}
        </p>
      )}
    </>
  )
}

import Link from "next/link"

export type PlaybookCardData = {
  slug: string
  title: string
  image: string | null
}

export function PlaybookCard({
  hrefBase = "/mockups/livepeer-agent/playbooks",
  playbook,
}: {
  hrefBase?: string
  playbook: PlaybookCardData
}) {
  return (
    <Link
      href={`${hrefBase}/${playbook.slug}`}
      className="group block rounded-sm focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none"
    >
      <article>
        <div
          className="aspect-square overflow-hidden rounded-sm bg-muted bg-cover bg-center"
          style={
            playbook.image
              ? { backgroundImage: `url("${playbook.image}")` }
              : undefined
          }
          aria-hidden="true"
        />
        <div className="mt-4 flex max-w-sm flex-col gap-1.5">
          <h2 className="line-clamp-2 font-heading text-xl font-normal">
            {playbook.title}
          </h2>
        </div>
      </article>
    </Link>
  )
}

import "server-only"

const origin = "https://storyboard.daydream.monster"

const titleOverrides: Record<string, string> = {
  "train-your-brand-aesthetic":
    "Krea 2 Open-Source: Train Your Brand Aesthetic",
}

const metadataOverrides: Record<
  string,
  {
    duration?: string
    durationLabel?: string
    budget?: string
    reliability?: string
  }
> = {
  "train-your-brand-aesthetic": {
    duration: "30s · 6–8m w/ LoRA",
    durationLabel: "Render time",
    budget: "$0.25 · $22.00 w/ LoRA",
    reliability: "4.3",
  },
}

export type SourcePlaybook = {
  slug: string
  title: string
  summary: string
  tags: string[]
  image: string | null
  deliverables: string[]
  stats: { value: string; label: string }[]
}

export type PlaybookDocument = {
  slug: string
  title: string
  tier?: string
  format?: string
  theme?: string
  persona?: string
  duration?: string
  durationLabel?: string
  budget?: string
  reliability?: string
  caps: string[]
  markdown: string
  brief: {
    yamlBlock: string
    fields: { name: string; defaultValue: string; hint: string }[]
    fenceStart: number
    fenceEnd: number
  } | null
  intro: string
  sections: { title: string; body: string }[]
  sourceUrl: string
}

function text(html: string) {
  return html
    .replace(/<br\s*\/?>/gi, " ")
    .replace(/<[^>]+>/g, "")
    .replace(/&amp;/g, "&")
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&rarr;/g, "→")
    .replace(/\s+/g, " ")
    .trim()
}

export async function getSourcePlaybooks(): Promise<SourcePlaybook[]> {
  const response = await fetch(`${origin}/playbooks/`, {
    next: { revalidate: 3600 },
  })

  if (!response.ok) throw new Error("Unable to load the Playbooks catalog")

  const html = await response.text()
  const matches = [
    ...html.matchAll(
      /<div class="card" data-href="\/playbooks\/viewer\.html\?p=([^"]+)" data-tags="([^"]*)">/g
    ),
  ].filter((match) => match[1] !== "DESIGN")

  return matches.map((match, index) => {
    const start = match.index ?? 0
    const end =
      matches[index + 1]?.index ?? html.indexOf("</div>\n\n  </div>", start)
    const block = html.slice(start, end > start ? end : undefined)
    const image = block.match(/<img src="([^"]+)"/)?.[1] ?? null
    const title =
      titleOverrides[match[1]] ??
      text(block.match(/<h2>([\s\S]*?)<\/h2>/)?.[1] ?? match[1])
    const summary = text(
      block.match(/<p class="tldr">([\s\S]*?)<\/p>/)?.[1] ?? ""
    )
    const deliverables = [
      ...block.matchAll(/<span class="deliv">([\s\S]*?)<\/span>/g),
    ].map((item) => text(item[1]))
    const stats = [
      ...block.matchAll(
        /<div class="stat"><strong>([\s\S]*?)<\/strong><span>([\s\S]*?)<\/span><\/div>/g
      ),
    ].map((item) => ({ value: text(item[1]), label: text(item[2]) }))

    return {
      slug: match[1],
      title,
      summary,
      tags: match[2].split(/\s+/).filter(Boolean),
      image: image
        ? image.startsWith("http")
          ? image
          : `${origin}${image}`
        : null,
      deliverables,
      stats,
    }
  })
}

function parseScalar(value: string | undefined) {
  return value?.trim().replace(/^["']|["']$/g, "")
}

export async function getPlaybookDocument(
  slug: string
): Promise<PlaybookDocument | null> {
  const sourceUrl = `${origin}/playbooks/${encodeURIComponent(slug)}.md`
  const response = await fetch(sourceUrl, { next: { revalidate: 3600 } })
  if (!response.ok) return null

  const markdown = await response.text()
  const frontmatterMatch = markdown.match(/^---\n([\s\S]*?)\n---\n/)
  const frontmatter = frontmatterMatch?.[1] ?? ""
  const body = markdown.slice(frontmatterMatch?.[0].length ?? 0)
  const fields = new Map(
    [...frontmatter.matchAll(/^([a-z_]+):\s*(.+)$/gm)].map((item) => [
      item[1],
      item[2],
    ])
  )
  const capsValue = fields.get("caps")
  const caps = capsValue
    ? capsValue
        .replace(/^\[|\]$/g, "")
        .split(",")
        .map((item) => parseScalar(item))
        .filter((item): item is string => Boolean(item))
    : []
  const heading = body.match(/^#\s+(.+)$/m)?.[1] ?? slug
  const intro = body.match(/^>\s+(.+(?:\n>\s+.*)*)/m)?.[1] ?? ""
  const fenceStart = markdown.indexOf(
    "```yaml",
    frontmatterMatch?.[0].length ?? 0
  )
  const fenceEnd =
    fenceStart === -1 ? -1 : markdown.indexOf("```", fenceStart + 7)
  const yamlBlock =
    fenceStart === -1 || fenceEnd === -1
      ? ""
      : markdown.slice(fenceStart + 7, fenceEnd).trim()
  const briefFields = yamlBlock.split("\n").flatMap((line) => {
    const trimmed = line.trim()
    if (!trimmed || trimmed.startsWith("#")) return []
    const match = /^([a-zA-Z_][\w]*)\s*:(.*)$/.exec(trimmed)
    if (!match) return []
    const rest = match[2]
    const hashIndex = rest.indexOf("#")
    return [
      {
        name: match[1],
        defaultValue:
          hashIndex === -1 ? rest.trim() : rest.slice(0, hashIndex).trim(),
        hint: hashIndex === -1 ? "" : rest.slice(hashIndex + 1).trim(),
      },
    ]
  })
  const sectionMatches = [...body.matchAll(/^##\s+(.+)$/gm)]
  const sections = sectionMatches.map((section, index) => {
    const start = (section.index ?? 0) + section[0].length
    const end = sectionMatches[index + 1]?.index ?? body.length
    return {
      title: section[1].trim(),
      body: body.slice(start, end).trim(),
    }
  })

  return {
    slug,
    title:
      titleOverrides[slug] ??
      parseScalar(fields.get("title")) ??
      heading.replace(/\s+⭐.*$/, ""),
    tier: parseScalar(fields.get("tier")),
    format: parseScalar(fields.get("format")),
    theme: parseScalar(fields.get("theme")),
    persona: parseScalar(fields.get("persona")),
    duration:
      metadataOverrides[slug]?.duration ?? parseScalar(fields.get("duration")),
    durationLabel: metadataOverrides[slug]?.durationLabel,
    budget:
      metadataOverrides[slug]?.budget ?? parseScalar(fields.get("budget_usd")),
    reliability:
      metadataOverrides[slug]?.reliability ??
      parseScalar(fields.get("reliability"))?.split("#")[0].trim(),
    caps,
    markdown,
    brief:
      yamlBlock && briefFields.length
        ? { yamlBlock, fields: briefFields, fenceStart, fenceEnd }
        : null,
    intro: intro
      .replace(/^>\s+/gm, "")
      .replace(/\*\*/g, "")
      .replace(/\bBRIEF\b/g, "details")
      .trim(),
    sections,
    sourceUrl,
  }
}
